const redact = (value) => String(value ?? '').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[redacted-email]');
const input = ($input.first() || {}).json || {};
const execution = input.execution || input;
const error = execution.error || {};
const workflow = execution.workflow || input.workflow || {};
const executionId = execution.id || input.executionId || '';
const nodeName = error.node || execution.lastNodeExecuted || '';
const message = redact(error.message || input.message || 'Unknown error');
const workflowName = workflow.name || 'Shakespeare Play Explorer';
const text = [
  'n8n workflow error',
  `workflow: ${workflowName}`,
  `execution_id: ${executionId}`,
  `node: ${nodeName}`,
  `error: ${message}`,
].join('\n');
return {
  json: {
    workflow_name: workflowName,
    execution_id: executionId,
    node: nodeName,
    error: message,
    subject: `n8n error: ${workflowName} [${executionId || 'unknown'}]`,
    text,
  },
};
